import { describe, expect, it } from 'vitest';
import { ERROR_CODES, SdrError, exitCode } from '../src/errors.js';

describe('ERROR_CODES', () => {
  it('覆盖 E1xx～E6xx 分段码', () => {
    expect(ERROR_CODES.GITHUB_TOKEN_INVALID).toBe('SDR-E101');
    expect(ERROR_CODES.GITHUB_RATE_LIMITED).toBe('SDR-E102');
    expect(ERROR_CODES.GITHUB_TIMEOUT).toBe('SDR-E103');
    expect(ERROR_CODES.GITHUB_PAGINATION_OVERFLOW).toBe('SDR-E104');
    expect(ERROR_CODES.FEISHU_AUTH_FAILED).toBe('SDR-E201');
    expect(ERROR_CODES.FEISHU_FIELD_MISSING).toBe('SDR-E202');
    expect(ERROR_CODES.WORK_BLOCKS_INVALID).toBe('SDR-E301');
    expect(ERROR_CODES.ENV_MISSING).toBe('SDR-E303');
    expect(ERROR_CODES.SMTP_AUTH_FAILED).toBe('SDR-E401');
    expect(ERROR_CODES.SMTP_TIMEOUT).toBe('SDR-E402');
    expect(ERROR_CODES.STORE_TRANSACTION_FAILED).toBe('SDR-E501');
    expect(ERROR_CODES.SOURCE_LINK_MISSING).toBe('SDR-E601');
  });
});

describe('SdrError', () => {
  it('携带 code / source / cause', () => {
    const cause = new Error('root');
    const err = new SdrError(ERROR_CODES.ENV_MISSING, '缺 GITHUB_TOKEN', {
      source: 'config',
      cause,
    });
    expect(err.code).toBe('SDR-E303');
    expect(err.source).toBe('config');
    expect(err.cause).toBe(cause);
    expect(err.name).toBe('SdrError');
  });
});

describe('exitCode', () => {
  it('E3xx → 9', () => {
    expect(exitCode(new SdrError(ERROR_CODES.ENV_MISSING, 'x'))).toBe(9);
    expect(exitCode(new SdrError(ERROR_CODES.WORK_BLOCKS_INVALID, 'x'))).toBe(9);
  });

  it('E4xx → 7', () => {
    expect(exitCode(new SdrError(ERROR_CODES.SMTP_AUTH_FAILED, 'x'))).toBe(7);
  });

  it('E6xx → 10', () => {
    expect(exitCode(new SdrError(ERROR_CODES.SOURCE_LINK_MISSING, 'x'))).toBe(10);
  });

  it('其余 SdrError 与未知错误 → 1', () => {
    expect(exitCode(new SdrError(ERROR_CODES.GITHUB_TIMEOUT, 'x'))).toBe(1);
    expect(exitCode(new SdrError(ERROR_CODES.STORE_TRANSACTION_FAILED, 'x'))).toBe(1);
    expect(exitCode(new Error('boom'))).toBe(1);
  });
});

import { afterEach, describe, expect, it } from 'vitest';
import { FixedClock, dayKey, dayWindow, minutesOfDay, toZonedIsoString } from '../src/clock.js';

describe('dayKey', () => {
  const previousTz = process.env.TZ;

  afterEach(() => {
    if (previousTz === undefined) {
      delete process.env.TZ;
    } else {
      process.env.TZ = previousTz;
    }
  });

  it('UTC 16:30 计入 Asia/Shanghai 次日', () => {
    const clock = new FixedClock(new Date('2026-11-25T16:30:00.000Z'));
    expect(dayKey(clock, clock.now())).toBe('2026-11-26');
  });

  it('UTC 15:59:59 仍属当日', () => {
    const clock = new FixedClock(new Date('2026-11-25T15:59:59.000Z'));
    expect(dayKey(clock, clock.now())).toBe('2026-11-25');
  });

  it('结果与进程 TZ 无关', () => {
    const at = new Date('2026-11-25T16:30:00.000Z');
    const clock = new FixedClock(at);
    process.env.TZ = 'UTC';
    const utc = dayKey(clock, at);
    process.env.TZ = 'Asia/Shanghai';
    const shanghai = dayKey(clock, at);
    expect(utc).toBe('2026-11-26');
    expect(shanghai).toBe(utc);
  });
});

describe('dayWindow', () => {
  it('返回左闭右开的本地日窗口', () => {
    const clock = new FixedClock(new Date('2026-11-25T12:00:00+08:00'));
    const { since, until } = dayWindow(clock, '2026-11-25');
    expect(dayKey(clock, since)).toBe('2026-11-25');
    expect(dayKey(clock, new Date(until.getTime() - 1))).toBe('2026-11-25');
    expect(dayKey(clock, until)).toBe('2026-11-26');
  });
});

describe('toZonedIsoString / minutesOfDay', () => {
  it('输出带 +08:00 偏移', () => {
    const clock = new FixedClock(new Date('2026-11-25T01:02:03.000Z'));
    const iso = toZonedIsoString(clock, clock.now());
    expect(iso).toMatch(/\+08:00$/);
    expect(iso.startsWith('2026-11-25T09:02:03')).toBe(true);
  });

  it('minutesOfDay 按本地墙钟计算', () => {
    const clock = new FixedClock(new Date('2026-11-25T01:30:00.000Z'));
    expect(minutesOfDay(clock, clock.now())).toBe(9 * 60 + 30);
  });
});

/**
 * 统一错误码（design.md §4.4 / HANDOVER §3.4）。
 */
export const ERROR_CODES = {
  GITHUB_TOKEN_INVALID: 'SDR-E101',
  GITHUB_RATE_LIMITED: 'SDR-E102',
  GITHUB_TIMEOUT: 'SDR-E103',
  GITHUB_PAGINATION_OVERFLOW: 'SDR-E104',
  FEISHU_AUTH_FAILED: 'SDR-E201',
  FEISHU_FIELD_MISSING: 'SDR-E202',
  WORK_BLOCKS_INVALID: 'SDR-E301',
  ENV_MISSING: 'SDR-E303',
  SMTP_AUTH_FAILED: 'SDR-E401',
  SMTP_TIMEOUT: 'SDR-E402',
  STORE_TRANSACTION_FAILED: 'SDR-E501',
  SOURCE_LINK_MISSING: 'SDR-E601',
} as const;

export type ErrorCode = (typeof ERROR_CODES)[keyof typeof ERROR_CODES];

export interface SdrErrorOptions {
  readonly source?: string;
  readonly cause?: unknown;
}

export class SdrError extends Error {
  readonly code: ErrorCode;
  readonly source: string | undefined;

  constructor(code: ErrorCode, message: string, options: SdrErrorOptions = {}) {
    super(message, { cause: options.cause });
    this.name = 'SdrError';
    this.code = code;
    this.source = options.source;
  }
}

/** E3xx→9，E4xx→7，E6xx→10，其余→1。采集部分/全失败由 CLI 聚合为 3/4。 */
export function exitCode(error: unknown): number {
  if (error instanceof SdrError) {
    if (error.code.startsWith('SDR-E3')) return 9;
    if (error.code.startsWith('SDR-E4')) return 7;
    if (error.code.startsWith('SDR-E6')) return 10;
  }
  return 1;
}

